digraph sample_ctrl_block {
    rankdir=LR;
    nodesep=0.5;
    ranksep=0.8;
    node [fontname="Helvetica", fontsize=12, shape=none, margin=0];
    edge [dir=none, penwidth=2.5, color="black"];

    // Generics box
    gen_box_sample_ctrl [label=<
        <TABLE BORDER="2" CELLBORDER="0" CELLSPACING="3" CELLPADDING="0" BGCOLOR="#c8f5c4" COLOR="#1a5c1a">
          <TR><TD PORT="g_RUN_CYCLES" ALIGN="LEFT" CELLPADDING="5">RUN_CYCLES = 1024</TD></TR>
        </TABLE>>];

    // Ports box
    port_box_sample_ctrl [label=<
        <TABLE BORDER="2" CELLBORDER="0" CELLSPACING="3" CELLPADDING="0" BGCOLOR="#fffde7" COLOR="#5d4200">
          <TR><TD PORT="i_clk" ALIGN="LEFT" CELLPADDING="5">&#x25B8; clk</TD><TD WIDTH="50"> </TD><TD PORT="o_capture_en" ALIGN="RIGHT" CELLPADDING="5">capture_en &#x25C2;</TD></TR>
          <TR><TD PORT="i_rst" ALIGN="LEFT" CELLPADDING="5">&#x25B8; rst</TD><TD WIDTH="50"> </TD><TD PORT="o_busy" ALIGN="RIGHT" CELLPADDING="5">busy &#x25C2;</TD></TR>
          <TR><TD PORT="i_start" ALIGN="LEFT" CELLPADDING="5">&#x25B8; start</TD><TD WIDTH="50"> </TD><TD PORT="o_state_code" ALIGN="RIGHT" CELLPADDING="5">state_code &#x25C2;</TD></TR>
          <TR><TD PORT="i_overflow" ALIGN="LEFT" CELLPADDING="5">&#x25B8; overflow</TD><TD WIDTH="50"> </TD><TD CELLPADDING="5"> </TD></TR>
        </TABLE>>];

    { rank=same; gen_box_sample_ctrl; port_box_sample_ctrl }
    gen_box_sample_ctrl -> port_box_sample_ctrl [style=invis, weight=100];

}

fsm.dot:
digraph sample_ctrl {
    rankdir=LR;
    node [shape=circle, style=filled, fontname=Helvetica, fontsize=12];
    edge [fontname=Helvetica, fontsize=10];

    __start [shape=point, width=0.2, fillcolor=black];

    IDLE [fillcolor=lightblue];
    ARMED [fillcolor=white];
    RUN [fillcolor=white];
    DONE [fillcolor=lightgreen];

    __start -> IDLE [label="reset"];

    IDLE -> ARMED [label="start = '1'"];
    ARMED -> RUN [label="always"];
    RUN -> DONE [label="run_last = '1'"];
    RUN -> DONE [label="overflow = '1'"];
    DONE -> IDLE [label="start = '0'"];
}
